input.command:
$env:PLANE_BASE_URL='https://plane.home.arpa'; $env:PLANE_WORKSPACE_SLUG='tvp-platform'; Remove-Item Env:SSL_CERT_FILE,Env:REQUESTS_CA_BUNDLE,Env:UV_SYSTEM_CERTS -ErrorAction SilentlyContinue
$line='{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"t","version":"0"}}}'
$psi=[Diagnostics.ProcessStartInfo]::new('pwsh',"-NoProfile -File `"$env:USERPROFILE\.claude\scripts\plane-mcp.ps1`" orchestrator")
$psi.RedirectStandardInput=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$psi.UseShellExecute=$false
$p=[Diagnostics.Process]::Start($psi)
$p.StandardInput.WriteLine($line);$p.StandardInput.Flush()
$t=$p.StandardOutput.ReadLineAsync(); if($t.Wait(30000)){ "STDOUT: " + $t.Result } else { "no stdout in 30s" }
$p.StandardInput.Close(); if(-not $p.WaitForExit(10000)){ $p.Kill($true); "killed test process" }
"EXIT: $($p.ExitCode)"; $err=$p.StandardError.ReadToEnd(); "STDERR (first 800): " + $err.Substring(0,[Math]::Min(800,$err.Length))
Select-String -Path "$env:USERPROFILE\.claude\scripts\plane-mcp.ps1" -Pattern 'uvx|& uv|uv ' | ForEach-Object { "uv ref line $($_.LineNumber): $($_.Line)" }

